    .where(eq(projectIssueCounters.projectId, projectId))
    .get();
  return Math.max(row?.value ?? 0, counter?.value ?? 0) + 1;
}

/** Raises the project's high-water mark to at least `number`. */
function recordIssuedNumber(projectId: ProjectId, number: number): void {
  getDb()
    .insert(projectIssueCounters)
    .values({ projectId, lastNumber: number })
    .onConflictDoUpdate({
      target: projectIssueCounters.projectId,
      set: {
        lastNumber: sql`max(${projectIssueCounters.lastNumber}, ${number})`,
      },
    })
    .run();
}

/**
 * Moves an issue into `toProjectId` under the target's next number, retiring
 * the old one in the source project. Returns the stored row.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const db = getDb();
  return db.transaction((tx) => {
    const current = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    recordIssuedNumber(current.projectId as ProjectId, current.number);
    const number = peekNextIssueNumber(orgId, toProjectId);
    recordIssuedNumber(toProjectId, number);

    const row = tx
      .update(issues)
      .set({
        projectId: toProjectId,
        number,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();
    return row;
  });
}

